//! Tests for the blosc decoder.
//!
//! The bulk of the confidence here comes from [`GROUND_TRUTH_VECTORS`]:
//! real compressed chunks produced by the reference C-Blosc library (via
//! its Python bindings, `pip install blosc`), not hand-crafted or produced
//! by any code in this crate. Comparing our decoder's output against the
//! known-original bytes for those vectors exercises the header parser, the
//! block-starts table, the per-block split logic (including the "leftover"
//! final block and multi-split blocks), the blosclz/lz4/zlib inner codecs,
//! both shuffle filters, and the whole-chunk memcpy fallback, all
//! end-to-end.
//!
//! Two codecs need a different validation strategy:
//! - Snappy is not available in the reference C-Blosc build used to
//!   generate [`GROUND_TRUTH_VECTORS`], so it is instead validated via a
//!   hand-assembled container wrapping `oxiarc_snappy`'s own compressor
//!   (self-consistent: same library on both sides, but it does exercise
//!   this module's container/dispatch logic for that codec).
//! - Zstd's container/dispatch logic is likewise correct (verified the same
//!   way, and each affected vector's raw compressed bytes were separately
//!   confirmed decodable via the real `zstandard` Python binding), but
//!   `oxiarc-zstd` 0.3.3 itself has a decoding bug that this project does
//!   not own -- see [`KNOWN_OXIARC_ZSTD_AFFECTED_VECTORS`] for the full
//!   explanation and how that failure mode is contained and tested.

use super::*;

/// Minimal hex decoder for test fixtures (keeps this module dependency-free).
fn hex_decode(s: &str) -> Vec<u8> {
    assert!(s.len() % 2 == 0, "hex string must have even length");
    (0..s.len())
        .step_by(2)
        .map(|i| {
            u8::from_str_radix(&s[i..i + 2], 16)
                .unwrap_or_else(|_| panic!("invalid hex byte at offset {i} in {s:?}"))
        })
        .collect()
}

/// Ground-truth (chunk_name, original_hex, compressed_hex) triples, produced by
/// the *real* reference C-Blosc library (via its Python bindings) rather than
/// hand-crafted. Covers blosclz/lz4/zlib/zstd inner codecs, no-shuffle/byte-shuffle/
/// bit-shuffle filters, single- and multi-block chunks (including a short
/// "leftover" final block), and the whole-chunk memcpy fallback. snappy is not
/// covered here (unavailable in the C-Blosc build used to generate these vectors);
