/// Vector names that are currently expected to fail, due to a pre-existing
/// bug in the `oxiarc-zstd` 0.3.3 dependency (not in this crate's own
/// code): its Huffman-coded-literals decoder either panics with an
/// arithmetic-underflow (`huffman.rs:263`, computing bitstream padding) or
/// returns a "corrupted data" parse error on certain short/highly
/// -compressible zstd frames -- exactly the kind of frame small,
/// artificially-repetitive test fixtures (and plenty of real sparse/
/// constant-ish scientific arrays) tend to produce. This was independently
/// confirmed to be a decoder-side bug, not a byte-extraction bug on our
/// side: every one of these vectors' zstd-compressed bytes was verified
/// to decode correctly (to the expected original) via the real `zstandard`
/// Python binding (a genuine libzstd), and this module's own container
/// parsing (header/bstarts/splits/shuffle) was independently re-derived and
/// cross-checked byte-for-byte before this bug was found. `decode_split`'s
/// [`call_third_party_codec`] wrapper ensures the panicking case still
/// surfaces as a clean [`tenflowers_core::TensorError`] rather than
/// unwinding out of this crate; see `test_known_oxiarc_zstd_limitation_is_a_clean_error`.
///
/// TODO(follow-up): once `oxiarc-zstd` fixes/upgrades past this, remove
/// this list (and this comment) and let these vectors round-trip normally
/// via `test_ground_truth_vectors_round_trip`.
const KNOWN_OXIARC_ZSTD_AFFECTED_VECTORS: &[&str] = &[
    "zstd_shuffle_f4",
    "zstd_bitshuffle_f4_multiblock",
    "zstd_noshuffle_bytes",
    "zstd_shuffle_i8_large_multiblock",
];

#[test]
fn test_ground_truth_vectors_round_trip() {
    assert!(
        GROUND_TRUTH_VECTORS.len() >= 16,
        "expected a substantial ground-truth vector set"
    );
    let mut failures = Vec::new();
    for (name, original_hex, compressed_hex) in GROUND_TRUTH_VECTORS {
        if KNOWN_OXIARC_ZSTD_AFFECTED_VECTORS.contains(name) {
            continue;
        }
        let original = hex_decode(original_hex);
        let compressed = hex_decode(compressed_hex);
        match decompress(&compressed) {
            Err(e) => failures.push(format!("{name}: decompress() failed: {e}")),
            Ok(decoded) if decoded != original => {
                failures.push(format!("{name}: decoded bytes did not match original"));
            }
            Ok(_) => {}
        }
    }
    assert!(
        failures.is_empty(),
        "{} ground-truth vectors failed:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn test_known_oxiarc_zstd_limitation_is_a_clean_error() {
    // Locks in the *safe* failure mode for KNOWN_OXIARC_ZSTD_AFFECTED_VECTORS:
    // decompress() must return an Err (never panic, and never silently
    // return wrong/partial bytes as if they were correct) for every one of
    // them. This also exercises `call_third_party_codec`'s panic-to-Result
    // conversion for the specific vector that panics inside oxiarc-zstd
    // rather than returning its own Err.
    assert!(!KNOWN_OXIARC_ZSTD_AFFECTED_VECTORS.is_empty());
    for name in KNOWN_OXIARC_ZSTD_AFFECTED_VECTORS {
        let (_, _, compressed_hex) = GROUND_TRUTH_VECTORS
            .iter()
            .find(|(n, _, _)| n == name)
            .unwrap_or_else(|| panic!("test: {name} must exist in GROUND_TRUTH_VECTORS"));
        let compressed = hex_decode(compressed_hex);
        let result = std::panic::catch_unwind(|| decompress(&compressed));
        match result {
            Ok(Err(_)) => {} // expected: clean, contained failure
            Ok(Ok(_)) => panic!(
                "{name}: unexpectedly succeeded -- if oxiarc-zstd was fixed, move this \
                 vector out of KNOWN_OXIARC_ZSTD_AFFECTED_VECTORS"
            ),
            Err(_) => panic!(
                "{name}: decompress() panicked instead of returning a clean Err; \
                 call_third_party_codec should have caught this"
            ),
        }
    }
}

#[test]
fn test_ground_truth_vector_names_are_unique() {
    let mut names: Vec<&str> = GROUND_TRUTH_VECTORS.iter().map(|(n, _, _)| *n).collect();
    names.sort_unstable();
    let mut deduped = names.clone();
    deduped.dedup();
    assert_eq!(names, deduped, "duplicate ground-truth vector name");
}

// ---------------------------------------------------------------------
// Header parsing
// ---------------------------------------------------------------------

#[test]
fn test_header_parse_rejects_too_short_input() {
    for len in 0..HEADER_LEN {
        let data = vec![0u8; len];
        let result = BloscHeader::parse(&data);
        assert!(result.is_err(), "header shorter than 16 bytes must error");
    }
}

#[test]
fn test_header_parse_reads_fields_in_expected_order() {
    // version=9, versionlz=8, flags=0xA3 (0b1010_0011): bit0 (byte-shuffle)
    // set, bit1 (memcpy) set, bit2 (bit-shuffle) clear, bit4 (no-split)
    // clear, bits5-7 = 0b101 = 5 (format code), typesize=4,
    // nbytes=0x11223344, blocksize=0x01020304, cbytes=0xAABBCCDD.
    let data: [u8; 16] = [
        9, 8, 0xA3, 4, // version, versionlz, flags, typesize
        0x44, 0x33, 0x22, 0x11, // nbytes LE
        0x04, 0x03, 0x02, 0x01, // blocksize LE
        0xDD, 0xCC, 0xBB, 0xAA, // cbytes LE
    ];
    let header = BloscHeader::parse(&data).expect("test: 16-byte header must parse");
    assert_eq!(header.typesize, 4);
    assert_eq!(header.nbytes, 0x1122_3344);
    assert_eq!(header.blocksize, 0x0102_0304);
    assert_eq!(header.cbytes, 0xAABB_CCDD);
    assert!(header.is_byte_shuffled()); // bit 0 set
    assert!(header.is_memcpyed()); // bit 1 set
    assert!(!header.is_bit_shuffled()); // bit 2 clear
    assert!(!header.no_split()); // bit 4 clear
    assert_eq!(header.format_code(), 0b101); // bits 5-7 = 101 = 5
}

#[test]
fn test_decompress_empty_nbytes_returns_empty_output() {
    // All-zero 16-byte header: nbytes == 0, so decompress() should short
    // circuit to an empty result without needing any block data.
    let data = [0u8; 16];
    let out = decompress(&data).expect("test: nbytes==0 should decode to empty output");
    assert!(out.is_empty());
}

#[test]
fn test_decompress_rejects_cbytes_larger_than_buffer() {
    let mut data = vec![0u8; 16];
    // cbytes = 1000, but the buffer is only 16 bytes long.
    data[12..16].copy_from_slice(&1000u32.to_le_bytes());
    let result = decompress(&data);
    assert!(
        result.is_err(),
        "declared cbytes exceeding buffer must error"
    );
}

#[test]
fn test_decompress_rejects_unknown_codec_id() {
    // nbytes=blocksize=8 (single, non-leftover block), format code = 7
    // (invalid: only 0..=4 are defined).
    let mut data = vec![0u8; 16 + 4];
    let total_len = data.len() as u32;
    data[2] = 7 << 5; // flags: format code 7, no shuffle/memcpy/no-split bits
    data[3] = 1; // typesize
    data[4..8].copy_from_slice(&8u32.to_le_bytes());
    data[8..12].copy_from_slice(&8u32.to_le_bytes());
    data[12..16].copy_from_slice(&total_len.to_le_bytes());
    data[16..20].copy_from_slice(&20u32.to_le_bytes()); // bstarts[0]
    let result = decompress(&data);
    assert!(result.is_err(), "unknown codec id must error");
    let message = result.expect_err("test: checked above").to_string();
    assert!(
        message.contains("codec"),
        "error message should mention the codec, got: {message}"
    );
}

#[test]
fn test_decompress_rejects_typesize_zero() {
    // Single 16-byte block, blosclz codec, no filters, but typesize == 0.
    let mut data = vec![0u8; 16 + 4];
    let total_len = data.len() as u32;
    data[2] = 0; // flags: blosclz, no shuffle/memcpy/no-split
    data[3] = 0; // typesize == 0 (invalid)
    data[4..8].copy_from_slice(&16u32.to_le_bytes());
    data[8..12].copy_from_slice(&16u32.to_le_bytes());
    data[12..16].copy_from_slice(&total_len.to_le_bytes());
    data[16..20].copy_from_slice(&20u32.to_le_bytes()); // bstarts[0]
    let result = decompress(&data);
    assert!(
        result.is_err(),
        "typesize == 0 must error, not divide by zero"
    );
    let message = result.expect_err("test: checked above").to_string();
    assert!(
        message.contains("typesize"),
        "error message should mention typesize, got: {message}"
    );
}

#[test]
fn test_decompress_rejects_blocksize_zero() {
    let mut data = vec![0u8; 16];
    data[3] = 1; // typesize
    data[4..8].copy_from_slice(&16u32.to_le_bytes()); // nbytes
                                                      // blocksize left as 0
    data[12..16].copy_from_slice(&16u32.to_le_bytes()); // cbytes
    let result = decompress(&data);
    assert!(
        result.is_err(),
        "blocksize == 0 must error, not divide by zero"
    );
}

#[test]
fn test_decompress_rejects_truncated_bstarts_table() {
    // Declares 2 blocks (nbytes=32, blocksize=16) but only provides enough
    // room in the buffer for the header, not the 8-byte bstarts table.
    let mut data = vec![0u8; 16];
    data[3] = 1;
    data[4..8].copy_from_slice(&32u32.to_le_bytes());
    data[8..12].copy_from_slice(&16u32.to_le_bytes());
    data[12..16].copy_from_slice(&16u32.to_le_bytes());
    let result = decompress(&data);
    assert!(result.is_err(), "truncated bstarts table must error");
}

#[test]
fn test_decompress_rejects_negative_split_length() {
    // One block, blosclz codec, whose split length prefix decodes to -1
    // when read as a signed i32 (0xFFFFFFFF).
    let mut data = vec![0u8; 16 + 4 + 4];
    let total_len = data.len() as u32;
    data[3] = 1; // typesize
    data[4..8].copy_from_slice(&8u32.to_le_bytes()); // nbytes
    data[8..12].copy_from_slice(&8u32.to_le_bytes()); // blocksize
    data[12..16].copy_from_slice(&total_len.to_le_bytes()); // cbytes
    data[16..20].copy_from_slice(&20u32.to_le_bytes()); // bstarts[0]
    data[20..24].copy_from_slice(&0xFFFF_FFFFu32.to_le_bytes()); // cbytes = -1
    let result = decompress(&data);
    assert!(result.is_err(), "negative split length must error");
    let message = result.expect_err("test: checked above").to_string();
    assert!(
        message.contains("negative"),
        "error message should mention the negative length, got: {message}"
    );
}

#[test]
fn test_decompress_rejects_truncated_split_data() {
    // Declares a split of 100 compressed bytes but the buffer only has
    // room for a handful.
    let mut data = vec![0u8; 16 + 4 + 4 + 4];
    let total_len = data.len() as u32;
    data[3] = 1;
    data[4..8].copy_from_slice(&8u32.to_le_bytes());
    data[8..12].copy_from_slice(&8u32.to_le_bytes());
    data[12..16].copy_from_slice(&total_len.to_le_bytes());
    data[16..20].copy_from_slice(&20u32.to_le_bytes());
    data[20..24].copy_from_slice(&100u32.to_le_bytes()); // claims 100 bytes
    let result = decompress(&data);
    assert!(result.is_err(), "truncated split data must error");
}

// ---------------------------------------------------------------------
// blosclz (isolated, bypassing the container format)
// ---------------------------------------------------------------------

#[test]
fn test_blosclz_decompress_empty_input() {
    let out = blosclz::decompress(&[], 0).expect("test: empty blosclz input decodes to empty");
    assert!(out.is_empty());
}

#[test]
fn test_blosclz_decompress_literal_only() {
    // ctrl=2 (literal branch, ctrl<32): run length = ctrl+1 = 3.
    let input = [0x02u8, b'A', b'B', b'C'];
    let out = blosclz::decompress(&input, 3).expect("test: literal-only blosclz should decode");
    assert_eq!(out, b"ABC");
}

#[test]
fn test_blosclz_decompress_long_match_run() {
    // Hand-assembled and hand-traced against the reference algorithm:
    //   [0x00, 'A']              -- literal run of 1 byte: "A"
    //   [0xE0, 0x0A, 0x00]       -- long-form match: distance=1 (a "run"),
    //                                length = 6 (escape) + 10 (continuation
    //                                byte) + 3 (bias) = 19
    //   [0x00, 'A']              -- trailing literal run of 1 byte: "A"
    // Total output: 1 + 19 + 1 = 21 copies of 'A'.
    let input = [0x00u8, b'A', 0xE0, 0x0A, 0x00, 0x00, b'A'];
    let out = blosclz::decompress(&input, 21).expect("test: hand-crafted long match should decode");
    assert_eq!(out, vec![b'A'; 21]);
}

#[test]
fn test_blosclz_decompress_truncated_literal_errors_not_panics() {
    // ctrl says 5 literal bytes follow, but only 2 are present.
    let input = [0x04u8, b'A', b'B'];
    let result = blosclz::decompress(&input, 5);
    assert!(
        result.is_err(),
        "truncated literal run must error, not panic"
    );
}

#[test]
fn test_blosclz_decompress_truncated_match_errors_not_panics() {
    // ctrl >= 32 starts a match token, but the stream ends before the
    // required offset byte.
    let input = [0x20u8];
    let result = blosclz::decompress(&input, 8);
    assert!(
        result.is_err(),
        "truncated match token must error, not panic"
    );
}

