#[test]
fn test_unshuffle_typesize_4_hand_worked_example() {
    // Four u32 (LE) elements: 0x04030201, 0x08070605, 0x0C0B0A09, 0x100F0E0D.
    let original: [u8; 16] = [
        0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F,
        0x10,
    ];
    // Byte-shuffled: all byte-0's, then all byte-1's, then byte-2's, byte-3's.
    let shuffled: [u8; 16] = [
        0x01, 0x05, 0x09, 0x0D, 0x02, 0x06, 0x0A, 0x0E, 0x03, 0x07, 0x0B, 0x0F, 0x04, 0x08, 0x0C,
        0x10,
    ];
    let unshuffled = filters::unshuffle(4, &shuffled);
    assert_eq!(unshuffled, original);
}

#[test]
fn test_unshuffle_typesize_8_round_trips_via_ground_truth() {
    // typesize == 8 unshuffle correctness is exercised end-to-end by several
    // GROUND_TRUTH_VECTORS entries (e.g. "blosclz_shuffle_i8_multiblock",
    // "zstd_shuffle_i8_large_multiblock") which use real i64 data shuffled
    // by the reference C-Blosc encoder; see test_ground_truth_vectors_round_trip.
    assert!(GROUND_TRUTH_VECTORS
        .iter()
        .any(|(name, _, _)| name.contains("shuffle_i8")));
}

#[test]
fn test_bitunshuffle_passthrough_when_element_count_not_multiple_of_eight() {
    // typesize=4, 12 bytes => 3 elements; 3 % 8 != 0, so bitunshuffle must
    // leave the block untouched (matches blosc_internal_bitunshuffle's
    // "else memcpy" branch).
    let data: Vec<u8> = (0..12u8).collect();
    let out = filters::bitunshuffle(4, &data).expect("test: bitunshuffle should not error");
    assert_eq!(out, data);
}

#[test]
fn test_bitunshuffle_rejects_typesize_zero() {
    let data = vec![0u8; 8];
    let result = filters::bitunshuffle(0, &data);
    assert!(
        result.is_err(),
        "typesize == 0 must error, not divide by zero"
    );
}

// ---------------------------------------------------------------------
// snappy: not present in the reference build used for GROUND_TRUTH_VECTORS,
// so validated via a hand-assembled container around oxiarc_snappy's own
// compressor instead (self-consistent, but exercises the real container
// parsing and dispatch logic for this codec).
// ---------------------------------------------------------------------

#[test]
fn test_snappy_split_self_consistent_round_trip() {
    let payload: Vec<u8> = (0..64u32).map(|i| (i % 17) as u8).collect();
    let compressed_split = oxiarc_snappy::compress(&payload);

    let mut data = Vec::with_capacity(16 + 4 + 4 + compressed_split.len());
    data.push(0); // version (unchecked)
    data.push(1); // versionlz (unchecked)
    data.push(2 << 5); // flags: format code 2 == snappy, no shuffle/memcpy
    data.push(1); // typesize (blocksize=64 with typesize=1 keeps splitting off)
    data.extend_from_slice(&64u32.to_le_bytes()); // nbytes
    data.extend_from_slice(&64u32.to_le_bytes()); // blocksize (single block)
    let cbytes = (16 + 4 + 4 + compressed_split.len()) as u32;
    data.extend_from_slice(&cbytes.to_le_bytes()); // cbytes
    data.extend_from_slice(&20u32.to_le_bytes()); // bstarts[0]
    data.extend_from_slice(&(compressed_split.len() as u32).to_le_bytes()); // split length prefix
    data.extend_from_slice(&compressed_split);

    assert_eq!(data.len(), cbytes as usize);

    let decoded = decompress(&data).expect("test: hand-assembled snappy chunk should decode");
    assert_eq!(decoded, payload);
}

#[test]
fn test_snappy_split_memcpy_fallback_when_cbytes_equals_neblock() {
    // A split whose declared compressed length equals the uncompressed
    // split size (neblock) must be treated as a raw copy, never handed to
    // the snappy decoder (whose own format would reject it).
    let payload: Vec<u8> = (0..16u8).collect();

    let mut data = Vec::with_capacity(16 + 4 + 4 + payload.len());
    data.push(0);
    data.push(1);
    data.push(2 << 5); // snappy format code, but this split is stored raw
    data.push(1); // typesize
    data.extend_from_slice(&16u32.to_le_bytes()); // nbytes
    data.extend_from_slice(&16u32.to_le_bytes()); // blocksize
    let cbytes = (16 + 4 + 4 + payload.len()) as u32;
    data.extend_from_slice(&cbytes.to_le_bytes());
    data.extend_from_slice(&20u32.to_le_bytes()); // bstarts[0]
    data.extend_from_slice(&(payload.len() as u32).to_le_bytes()); // cbytes == neblock
    data.extend_from_slice(&payload);

    let decoded = decompress(&data).expect("test: memcpy'ed split should decode");
    assert_eq!(decoded, payload);
}

// ---------------------------------------------------------------------
// Top-level memcpy'ed chunk (flags bit 1), independent of the ground-truth
// vector that also covers this path.
// ---------------------------------------------------------------------

#[test]
fn test_decompress_whole_chunk_memcpy_hand_assembled() {
    let payload: Vec<u8> = (0..40u8).collect();
    let mut data = Vec::with_capacity(16 + payload.len());
    data.push(0);
    data.push(1);
    data.push(FLAG_MEMCPYED);
    data.push(1);
    data.extend_from_slice(&(payload.len() as u32).to_le_bytes());
    data.extend_from_slice(&(payload.len() as u32).to_le_bytes());
    data.extend_from_slice(&((16 + payload.len()) as u32).to_le_bytes());
    data.extend_from_slice(&payload);

    let decoded = decompress(&data).expect("test: memcpy'ed chunk should decode");
    assert_eq!(decoded, payload);
}
